1	import { useState, useEffect, useRef, useCallback } from "react";
2	import { toast } from "sonner";
3	import { Globe, Copy, ExternalLink, Loader2, Save, Eye } from "lucide-react";
4	import SidebarLayout from "@/components/SidebarLayout";
5	import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
6	import { Button } from "@/components/ui/button";
7	import { Input } from "@/components/ui/input";
8	import { Textarea } from "@/components/ui/textarea";
9	import { Label } from "@/components/ui/label";
10	import { Switch } from "@/components/ui/switch";
11	import { Badge } from "@/components/ui/badge";
12	import { Skeleton } from "@/components/ui/skeleton";
13	import {
14	  Table,
15	  TableBody,
16	  TableCell,
17	  TableHead,
18	  TableHeader,
19	  TableRow,
20	} from "@/components/ui/table";
21	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
22	import { supabase } from "@/integrations/supabase/client";
23	import { useAuth } from "@/hooks/useAuth";
24	import { useTeam } from "@/hooks/useTeam";
25	
26	// ---------------------------------------------------------------------------
27	// Types
28	// ---------------------------------------------------------------------------
29	
30	interface CareerPageConfig {
31	  id: string;
32	  team_id: string;
33	  company_name: string | null;
34	  slug: string | null;
35	  logo_url: string | null;
36	  brand_color: string | null;
37	  tagline: string | null;
38	  about: string | null;
39	  is_active: boolean;
40	}
41	
42	interface CareerJob {
43	  id: string;
44	  title: string | null;
45	  location: string | null;
46	  department: string | null;
47	  employment_type: string | null;
48	  is_published: boolean | null;
49	  status: string | null;
50	}
51	
52	type SlugStatus = "idle" | "checking" | "available" | "taken";
53	
54	// ---------------------------------------------------------------------------
55	// Helpers
56	// ---------------------------------------------------------------------------
57	
58	function slugify(name: string): string {
59	  const raw = name
60	    .toLowerCase()
61	    .replace(/[^a-z0-9]+/g, "-")
62	    .replace(/^-|-$/g, "")
63	    .slice(0, 60);
64	  // DB constraint requires minimum 3 chars starting and ending with alphanumeric.
65	  // Pad short slugs with a numeric suffix so they always pass the constraint.
66	  if (raw.length < 3) return raw.padEnd(3, "1");
67	  return raw;
68	}
69	
70	// DB constraint only accepts 6-digit hex (#rrggbb).
71	// 3-digit shorthand like #fff is NOT accepted by the career_page_brand_color_format check.
72	function isValidHex(value: string): boolean {
73	  return /^#[0-9A-Fa-f]{6}$/.test(value);
74	}
75	
76	// ---------------------------------------------------------------------------
77	// Skeleton components
78	// ---------------------------------------------------------------------------
79	
80	function ConfigSkeleton() {
81	  return (
82	    <div className="space-y-5">
83	      {[1, 2, 3, 4, 5, 6].map((i) => (
84	        <div key={i} className="space-y-1.5">
85	          <Skeleton className="h-4 w-24" />
86	          <Skeleton className="h-9 w-full" />
87	        </div>
88	      ))}
89	      <Skeleton className="h-9 w-28 mt-2" />
90	    </div>
91	  );
92	}
93	
94	function JobsSkeleton() {
95	  return (
96	    <div className="space-y-0">
97	      {[1, 2, 3].map((i) => (
98	        <div key={i} className="flex items-center gap-4 px-4 py-3 border-b border-border last:border-0">
99	          <Skeleton className="h-4 flex-1" />
100	          <Skeleton className="h-4 w-24" />
101	          <Skeleton className="h-4 w-20" />
102	          <Skeleton className="h-5 w-10 rounded-full" />
103	        </div>
104	      ))}
105	    </div>
106	  );
107	}
108	
109	// ---------------------------------------------------------------------------
110	// Slug status indicator
111	// ---------------------------------------------------------------------------
112	
113	function SlugStatusBadge({ status }: { status: SlugStatus }) {
114	  if (status === "idle") return null;
115	  if (status === "checking") {
116	    return (
117	      <span className="flex items-center gap-1 text-xs text-muted-foreground">
118	        <Loader2 className="h-3 w-3 animate-spin" />
119	        Checking…
120	      </span>
121	    );
122	  }
123	  if (status === "available") {
124	    return (
125	      <Badge variant="outline" className="text-xs border-green-500/50 text-green-600 dark:text-green-400">
126	        Available
127	      </Badge>
128	    );
129	  }
130	  return (
131	    <Badge variant="outline" className="text-xs border-destructive/50 text-destructive">
132	      Already taken
133	    </Badge>
134	  );
135	}
136	
137	// ---------------------------------------------------------------------------
138	// Main page
139	// ---------------------------------------------------------------------------
140	
141	const CareerSettings = () => {
142	  const { user } = useAuth();
143	  const { team } = useTeam();
144	  const queryClient = useQueryClient();
145	
146	  const teamId = team?.id ?? null;
147	  const userId = user?.id ?? null;
148	
149	  // ----- Form state -----
150	  const [companyName, setCompanyName] = useState("");
151	  const [slug, setSlug] = useState("");
152	  const [logoUrl, setLogoUrl] = useState("");
153	  const [brandColor, setBrandColor] = useState("#6366f1");
154	  const [tagline, setTagline] = useState("");
155	  const [about, setAbout] = useState("");
156	  const [isActive, setIsActive] = useState(false);
157	  const [configId, setConfigId] = useState<string | null>(null);
158	  const [isSaving, setIsSaving] = useState(false);
159	  const [slugStatus, setSlugStatus] = useState<SlugStatus>("idle");
160	  const [slugManuallyEdited, setSlugManuallyEdited] = useState(false);
161	  const [togglingJobId, setTogglingJobId] = useState<string | null>(null);
162	
163	  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
164	
165	  // ----- Career page URL -----
166	  const careerPageUrl = slug ? `${window.location.origin}/careers/${slug}` : null;
167	
168	  // ----- Fetch config -----
169	  const { data: configData, isLoading: configLoading } = useQuery({
170	    queryKey: ["career-page-config", teamId],
171	    queryFn: async () => {
172	      if (!teamId) return null;
173	      const { data, error } = await (supabase as any)
174	        .from("career_page_config")
175	        .select("*")
176	        .eq("team_id", teamId)
177	        .maybeSingle();
178	      if (error) throw new Error(error.message);
179	      return data as CareerPageConfig | null;
180	    },
181	    enabled: !!teamId,
182	    staleTime: 60_000,
183	  });
184	
185	  // Populate form when config loads
186	  useEffect(() => {
187	    if (configData) {
188	      setConfigId(configData.id);
189	      setCompanyName(configData.company_name ?? "");
190	      setSlug(configData.slug ?? "");
191	      setLogoUrl(configData.logo_url ?? "");
192	      setBrandColor(configData.brand_color ?? "#6366f1");
193	      setTagline(configData.tagline ?? "");
194	      setAbout(configData.about ?? "");
195	      setIsActive(configData.is_active ?? false);
196	      setSlugManuallyEdited(true); // Don't auto-overwrite on subsequent renders
197	    } else if (!configLoading && team?.name) {
198	      // Pre-fill from team name on first load
199	      setCompanyName(team.name);
200	      const auto = slugify(team.name);
201	      setSlug(auto);
202	    }
203	  }, [configData, configLoading, team?.name]);
204	
205	  // ----- Fetch jobs -----
206	  const { data: jobs = [], isLoading: jobsLoading } = useQuery({
207	    queryKey: ["career-jobs", userId],
208	    queryFn: async () => {
209	      if (!userId) return [];
210	      const { data, error } = await (supabase as any)
211	        .from("jobs")
212	        .select("id, title, location, department, employment_type, is_published, status")
213	        .eq("user_id", userId)
214	        .order("created_at", { ascending: false });
215	      if (error) throw new Error(error.message);
216	      return (data ?? []) as CareerJob[];
217	    },
218	    enabled: !!userId,
219	    staleTime: 30_000,
220	  });
221	
222	  // ----- Slug auto-gen from company name -----
223	  const handleCompanyNameChange = (value: string) => {
224	    setCompanyName(value);
225	    if (!slugManuallyEdited) {
226	      const auto = slugify(value);
227	      setSlug(auto);
228	      triggerSlugCheck(auto);
229	    }
230	  };
231	
232	  // ----- Slug check debounce -----
233	  const triggerSlugCheck = useCallback(
234	    (value: string) => {
235	      if (debounceRef.current) clearTimeout(debounceRef.current);
236	      if (!value || !teamId) {
237	        setSlugStatus("idle");
238	        return;
239	      }
240	      setSlugStatus("checking");
241	      debounceRef.current = setTimeout(async () => {
242	        try {
243	          const { data, error } = await (supabase as any).rpc("is_career_slug_available", {
244	            p_slug: value,
245	            p_team_id: teamId,
246	          });
247	          if (error) throw error;
248	          setSlugStatus(data === true ? "available" : "taken");
249	        } catch {
250	          setSlugStatus("idle");
251	        }
252	      }, 600);
253	    },
254	    [teamId]
255	  );
256	
257	  const handleSlugChange = (value: string) => {
258	    const clean = value.toLowerCase().replace(/[^a-z0-9-]/g, "").slice(0, 60);
259	    setSlug(clean);
260	    setSlugManuallyEdited(true);
261	    triggerSlugCheck(clean);
262	  };
263	
264	  // Cleanup debounce on unmount
265	  useEffect(() => {
266	    return () => {
267	      if (debounceRef.current) clearTimeout(debounceRef.current);
268	    };
269	  }, []);
270	
271	  // ----- Save config -----
272	  const handleSave = async () => {
273	    if (!teamId) {
274	      toast.error("No team found. Create a team first.");
275	      return;
276	    }
277	    if (!companyName.trim()) {
278	      toast.error("Company name is required.");
279	      return;
280	    }
281	    if (!slug.trim()) {
282	      toast.error("URL slug is required.");
283	      return;
284	    }
285	    // DB constraint: ^[a-z0-9][a-z0-9\-]{1,58}[a-z0-9]$ — minimum 3 chars, must start/end with alphanumeric
286	    if (slug.length < 3) {
287	      toast.error("Slug must be at least 3 characters.");
288	      return;
289	    }
290	    if (!/^[a-z0-9]/.test(slug) || !/[a-z0-9]$/.test(slug)) {
291	      toast.error("Slug must start and end with a letter or number.");
292	      return;
293	    }
294	    if (slugStatus === "taken") {
295	      toast.error("That slug is already taken. Choose a different one.");
296	      return;
297	    }
298	
299	    setIsSaving(true);
300	    try {
301	      const payload = {
302	        team_id: teamId,
303	        company_name: companyName.trim(),
304	        slug: slug.trim(),
305	        logo_url: logoUrl.trim() || null,
306	        brand_color: isValidHex(brandColor) ? brandColor : "#6366f1",
307	        tagline: tagline.trim() || null,
308	        about: about.trim() || null,
309	        is_active: isActive,
310	      };
311	
312	      if (configId) {
313	        const { error } = await (supabase as any)
314	          .from("career_page_config")
315	          .update(payload)
316	          .eq("id", configId);
317	        if (error) throw error;
318	      } else {
319	        const { data: inserted, error } = await (supabase as any)
320	          .from("career_page_config")
321	          .insert(payload)
322	          .select("id")
323	          .single();
324	        if (error) throw error;
325	        // Capture the new row id so subsequent saves use UPDATE, not INSERT.
326	        // Without this, a second save attempt would hit the UNIQUE(team_id) constraint.
327	        if (inserted?.id) {
328	          setConfigId(inserted.id as string);
329	        }
330	      }
331	
332	      toast.success("Career page saved");
333	      queryClient.invalidateQueries({ queryKey: ["career-page-config", teamId] });
334	    } catch (err: unknown) {
335	      const msg = err instanceof Error ? err.message : "Failed to save career page";
336	      toast.error(msg);
337	    } finally {
338	      setIsSaving(false);
339	    }
340	  };
341	
342	  // ----- Toggle job published -----
343	  const toggleJobPublished = useMutation({
344	    mutationFn: async ({ jobId, current }: { jobId: string; current: boolean }) => {
345	      const { error } = await (supabase as any)
346	        .from("jobs")
347	        .update({ is_published: !current })
348	        .eq("id", jobId);
349	      if (error) throw new Error(error.message);
350	      return { jobId, newValue: !current };
351	    },
352	    onMutate: ({ jobId }) => {
353	      setTogglingJobId(jobId);
354	    },
355	    onSuccess: ({ jobId, newValue }) => {
356	      queryClient.setQueryData(["career-jobs", userId], (old: CareerJob[] | undefined) =>
357	        (old ?? []).map((j) => (j.id === jobId ? { ...j, is_published: newValue } : j))
358	      );
359	      toast.success(newValue ? "Job published to career page" : "Job unpublished");
360	    },
361	    onError: (err: unknown) => {
362	      const msg = err instanceof Error ? err.message : "Failed to update job";
363	      toast.error(msg);
364	    },
365	    onSettled: () => {
366	      setTogglingJobId(null);
367	    },
368	  });
369	
370	  // ----- Clipboard copy -----
371	  function copyUrl() {
372	    if (!careerPageUrl) return;
373	    navigator.clipboard.writeText(careerPageUrl).then(
374	      () => toast.success("Link copied"),
375	      () => toast.error("Could not copy link")
376	    );
377	  }
378	
379	  // ---------------------------------------------------------------------------
380	  // Render
381	  // ---------------------------------------------------------------------------
382	
383	  return (
384	    <SidebarLayout>
385	      <main className="w-full max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
386	        <div className="flex items-start justify-between mb-1">
387	          <h1 className="text-2xl font-bold text-foreground">Career Page</h1>
388	          {isActive && careerPageUrl && (
389	            <div className="flex items-center gap-1.5">
390	              <Badge variant="outline" className="text-xs border-green-500/50 text-green-600 dark:text-green-400 gap-1">
391	                <Eye className="h-3 w-3" />
392	                Live
393	              </Badge>
394	              <Button
395	                variant="ghost"
396	                size="icon"
397	                className="h-7 w-7"
398	                onClick={copyUrl}
399	                aria-label="Copy career page URL"
400	              >
401	                <Copy className="h-3.5 w-3.5" />
402	              </Button>
403	              <Button
404	                variant="ghost"
405	                size="icon"
406	                className="h-7 w-7"
407	                onClick={() => window.open(careerPageUrl, "_blank")}
408	                aria-label="Open career page"
409	              >
410	                <ExternalLink className="h-3.5 w-3.5" />
411	              </Button>
412	            </div>
413	          )}
414	        </div>
415	        <p className="text-sm text-muted-foreground mb-6">
416	          Customize your public career page and manage which jobs are visible to candidates.
417	        </p>
418	
419	        <div className="space-y-6">
420	          {/* ---------------------------------------------------------------- */}
421	          {/* Card 1: Configuration                                             */}
422	          {/* ---------------------------------------------------------------- */}
423	          <Card className="border border-border/60 shadow-sm">
424	            <CardHeader className="pb-3">
425	              <CardTitle className="text-sm font-semibold flex items-center gap-2">
426	                <Globe className="h-4 w-4 text-primary" />
427	                Career Page Configuration
428	              </CardTitle>
429	              <CardDescription className="text-xs">
430	                Set up your branded career page. Share the link with candidates.
431	              </CardDescription>
432	            </CardHeader>
433	            <CardContent>
434	              {configLoading ? (
435	                <ConfigSkeleton />
436	              ) : (
437	                <div className="space-y-5">
438	                  {/* Company name */}
439	                  <div className="space-y-1.5">
440	                    <Label htmlFor="company-name" className="text-xs font-medium">
441	                      Company name
442	                    </Label>
443	                    <Input
444	                      id="company-name"
445	                      placeholder="Acme Corp"
446	                      value={companyName}
447	                      onChange={(e) => handleCompanyNameChange(e.target.value)}
448	                      disabled={isSaving}
449	                    />
450	                  </div>
451	
452	                  {/* Slug */}
453	                  <div className="space-y-1.5">
454	                    <div className="flex items-center justify-between">
455	                      <Label htmlFor="slug" className="text-xs font-medium">
456	                        URL slug
457	                      </Label>
458	                      <SlugStatusBadge status={slugStatus} />
459	                    </div>
460	                    <div className="flex items-center rounded-md border border-input bg-background ring-offset-background focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-2 overflow-hidden">
461	                      <span className="flex items-center pl-3 pr-1 text-xs text-muted-foreground whitespace-nowrap shrink-0 select-none">
462	                        /careers/
463	                      </span>
464	                      <input
465	                        id="slug"
466	                        className="flex-1 py-2 pr-3 text-sm bg-transparent outline-none placeholder:text-muted-foreground"
467	                        placeholder="acme-corp"
468	                        value={slug}
469	                        onChange={(e) => handleSlugChange(e.target.value)}
470	                        disabled={isSaving}
471	                        spellCheck={false}
472	                        aria-describedby="slug-hint"
473	                      />
474	                    </div>
475	                    <p id="slug-hint" className="text-xs text-muted-foreground">
476	                      Lowercase letters, numbers, and hyphens only.
477	                    </p>
478	                  </div>
479	
480	                  {/* Logo URL */}
481	                  <div className="space-y-1.5">
482	                    <Label htmlFor="logo-url" className="text-xs font-medium">
483	                      Logo URL
484	                    </Label>
485	                    <Input
486	                      id="logo-url"
487	                      placeholder="https://example.com/logo.png"
488	                      value={logoUrl}
489	                      onChange={(e) => setLogoUrl(e.target.value)}
490	                      disabled={isSaving}
491	                      type="url"
492	                    />
493	                  </div>
494	
495	                  {/* Brand color */}
496	                  <div className="space-y-1.5">
497	                    <Label className="text-xs font-medium">Brand color</Label>
498	                    <div className="flex items-center gap-2">
499	                      <div className="relative h-9 w-14 shrink-0">
500	                        <input
501	                          type="color"
502	                          className="absolute inset-0 h-full w-full cursor-pointer rounded-md border border-input opacity-0"
503	                          value={isValidHex(brandColor) ? brandColor : "#6366f1"}
504	                          onChange={(e) => setBrandColor(e.target.value)}
505	                          disabled={isSaving}
506	                          aria-label="Pick brand color"
507	                        />
508	                        <div
509	                          className="h-full w-full rounded-md border border-input"
510	                          style={{ backgroundColor: isValidHex(brandColor) ? brandColor : "#6366f1" }}
511	                        />
512	                      </div>
513	                      <Input
514	                        placeholder="#6366f1"
515	                        value={brandColor}
516	                        onChange={(e) => setBrandColor(e.target.value)}
517	                        disabled={isSaving}
518	                        className="font-mono text-sm w-32"
519	                        maxLength={7}
520	                        aria-label="Brand color hex code"
521	                      />
522	                      {!isValidHex(brandColor) && brandColor.length > 0 && (
523	                        <span className="text-xs text-destructive">Use 6-digit hex (e.g. #6366f1)</span>
524	                      )}
525	                    </div>
526	                  </div>
527	
528	                  {/* Tagline */}
529	                  <div className="space-y-1.5">
530	                    <Label htmlFor="tagline" className="text-xs font-medium">
531	                      Tagline
532	                    </Label>
533	                    <Input
534	                      id="tagline"
535	                      placeholder="We're building the future of work"
536	                      value={tagline}
537	                      onChange={(e) => setTagline(e.target.value)}
538	                      disabled={isSaving}
539	                      maxLength={160}
540	                    />
541	                  </div>
542	
543	                  {/* About */}
544	                  <div className="space-y-1.5">
545	                    <Label htmlFor="about" className="text-xs font-medium">
546	                      About
547	                    </Label>
548	                    <Textarea
549	                      id="about"
550	                      placeholder="Tell candidates about your company, culture, and mission…"
551	                      value={about}
552	                      onChange={(e) => setAbout(e.target.value)}
553	                      disabled={isSaving}
554	                      rows={4}
555	                      className="resize-none text-sm"
556	                      maxLength={2000}
557	                    />
558	                  </div>
559	
560	                  {/* Active toggle */}
561	                  <div className="flex items-center justify-between rounded-lg border border-border p-3">
562	                    <div className="space-y-0.5">
563	                      <Label htmlFor="is-active" className="text-sm font-medium cursor-pointer">
564	                        Publish career page
565	                      </Label>
566	                      <p className="text-xs text-muted-foreground">
567	                        Make your career page publicly accessible to candidates.
568	                      </p>
569	                    </div>
570	                    <Switch
571	                      id="is-active"
572	                      checked={isActive}
573	                      onCheckedChange={setIsActive}
574	                      disabled={isSaving}
575	                      aria-label="Publish career page"
576	                    />
577	                  </div>
578	
579	                  {/* Preview link (when active + slug set) */}
580	                  {isActive && careerPageUrl && (
581	                    <div className="flex items-center gap-2 rounded-md bg-muted/50 px-3 py-2">
582	                      <Globe className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
583	                      <a
584	                        href={careerPageUrl}
585	                        target="_blank"
586	                        rel="noopener noreferrer"
587	                        className="flex-1 text-xs text-primary truncate hover:underline"
588	                      >
589	                        {careerPageUrl}
590	                      </a>
591	                      <button
592	                        onClick={copyUrl}
593	                        className="shrink-0 text-muted-foreground hover:text-foreground transition-colors"
594	                        aria-label="Copy career page URL"
595	                        type="button"
596	                      >
597	                        <Copy className="h-3.5 w-3.5" />
598	                      </button>
599	                      <a
600	                        href={careerPageUrl}
601	                        target="_blank"
602	                        rel="noopener noreferrer"
603	                        className="shrink-0 text-muted-foreground hover:text-foreground transition-colors"
604	                        aria-label="Open in new tab"
605	                      >
606	                        <ExternalLink className="h-3.5 w-3.5" />
607	                      </a>
608	                    </div>
609	                  )}
610	
611	                  {/* Save button */}
612	                  <div className="flex justify-end pt-1">
613	                    <Button
614	                      onClick={handleSave}
615	                      disabled={isSaving || slugStatus === "taken"}
616	                      className="gap-1.5"
617	                    >
618	                      {isSaving ? (
619	                        <Loader2 className="h-4 w-4 animate-spin" />
620	                      ) : (
621	                        <Save className="h-4 w-4" />
622	                      )}
623	                      Save changes
624	                    </Button>
625	                  </div>
626	                </div>
627	              )}
628	            </CardContent>
629	          </Card>
630	
631	          {/* ---------------------------------------------------------------- */}
632	          {/* Card 2: Published Jobs                                            */}
633	          {/* ---------------------------------------------------------------- */}
