                                <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
                              </div>
                            ) : (
                              <Switch
                                checked={published}
                                onCheckedChange={() =>
                                  toggleJobPublished.mutate({ jobId: job.id, current: published })
                                }
                                disabled={isToggling}
                                aria-label={`${published ? "Unpublish" : "Publish"} ${job.title ?? "job"}`}
                              />
                            )}
                          </TableCell>
                        </TableRow>
                      );
                    })}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </div>
      </main>
    </SidebarLayout>
  );
};

export default CareerSettings;

