1	import { useState, useEffect, useRef, useCallback } from "react";
2	import { toast } from "sonner";
3	import {
4	  Globe, Copy, ExternalLink, Loader2, Save, Eye, Plus, Trash2,
5	  Link2, Twitter, Instagram, Facebook, Linkedin, Code2, Info,
6	  Users, Star,
7	} from "lucide-react";
8	import SidebarLayout from "@/components/SidebarLayout";
9	import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
10	import { Button } from "@/components/ui/button";
11	import { Input } from "@/components/ui/input";
12	import { Textarea } from "@/components/ui/textarea";
13	import { Label } from "@/components/ui/label";
14	import { Switch } from "@/components/ui/switch";
15	import { Badge } from "@/components/ui/badge";
16	import { Skeleton } from "@/components/ui/skeleton";
17	import {
18	  Table,
19	  TableBody,
20	  TableCell,
21	  TableHead,
22	  TableHeader,
23	  TableRow,
24	} from "@/components/ui/table";
25	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
26	import { supabase } from "@/integrations/supabase/client";
27	import { useAuth } from "@/hooks/useAuth";
28	import { useTeam } from "@/hooks/useTeam";
29	
30	// ---------------------------------------------------------------------------
31	// Types
32	// ---------------------------------------------------------------------------
33	
34	interface CareerPageConfig {
35	  id: string;
36	  team_id: string;
37	  company_name: string | null;
38	  slug: string | null;
39	  logo_url: string | null;
40	  brand_color: string | null;
41	  tagline: string | null;
42	  about: string | null;
43	  is_active: boolean;
44	}
45	
46	interface CareerJob {
47	  id: string;
48	  title: string | null;
49	  location: string | null;
50	  department: string | null;
51	  employment_type: string | null;
52	  is_published: boolean | null;
53	  status: string | null;
54	  view_count: number | null;
55	  apply_count: number | null;
56	}
57	
58	type SlugStatus = "idle" | "checking" | "available" | "taken";
59	
60	// ---------------------------------------------------------------------------
61	// Helpers
62	// ---------------------------------------------------------------------------
63	
64	function slugify(name: string): string {
65	  const raw = name
66	    .toLowerCase()
67	    .replace(/[^a-z0-9]+/g, "-")
68	    .replace(/^-|-$/g, "")
69	    .slice(0, 60);
70	  // DB constraint requires minimum 3 chars starting and ending with alphanumeric.
71	  // Pad short slugs with a numeric suffix so they always pass the constraint.
72	  if (raw.length < 3) return raw.padEnd(3, "1");
73	  return raw;
74	}
75	
76	// DB constraint only accepts 6-digit hex (#rrggbb).
77	// 3-digit shorthand like #fff is NOT accepted by the career_page_brand_color_format check.
78	function isValidHex(value: string): boolean {
79	  return /^#[0-9A-Fa-f]{6}$/.test(value);
80	}
81	
82	// ---------------------------------------------------------------------------
83	// Skeleton components
84	// ---------------------------------------------------------------------------
85	
86	function ConfigSkeleton() {
87	  return (
88	    <div className="space-y-5">
89	      {[1, 2, 3, 4, 5, 6].map((i) => (
90	        <div key={i} className="space-y-1.5">
91	          <Skeleton className="h-4 w-24" />
92	          <Skeleton className="h-9 w-full" />
93	        </div>
94	      ))}
95	      <Skeleton className="h-9 w-28 mt-2" />
96	    </div>
97	  );
98	}
99	
100	function JobsSkeleton() {
101	  return (
102	    <div className="space-y-0">
103	      {[1, 2, 3].map((i) => (
104	        <div key={i} className="flex items-center gap-4 px-4 py-3 border-b border-border last:border-0">
105	          <Skeleton className="h-4 flex-1" />
106	          <Skeleton className="h-4 w-24" />
107	          <Skeleton className="h-4 w-20" />
108	          <Skeleton className="h-5 w-10 rounded-full" />
109	        </div>
110	      ))}
111	    </div>
112	  );
113	}
114	
115	// ---------------------------------------------------------------------------
116	// Slug status indicator
117	// ---------------------------------------------------------------------------
118	
119	function SlugStatusBadge({ status }: { status: SlugStatus }) {
120	  if (status === "idle") return null;
121	  if (status === "checking") {
122	    return (
123	      <span className="flex items-center gap-1 text-xs text-muted-foreground">
124	        <Loader2 className="h-3 w-3 animate-spin" />
125	        Checking…
126	      </span>
127	    );
128	  }
129	  if (status === "available") {
130	    return (
131	      <Badge variant="outline" className="text-xs border-green-500/50 text-green-600 dark:text-green-400">
132	        Available
133	      </Badge>
134	    );
135	  }
136	  return (
137	    <Badge variant="outline" className="text-xs border-destructive/50 text-destructive">
138	      Already taken
139	    </Badge>
140	  );
141	}
142	
143	// ---------------------------------------------------------------------------
144	// Main page
145	// ---------------------------------------------------------------------------
146	
147	const CareerSettings = () => {
148	  const { user } = useAuth();
149	  const { team } = useTeam();
150	  const queryClient = useQueryClient();
151	
152	  const teamId = team?.id ?? null;
153	  const userId = user?.id ?? null;
154	
155	  // ----- Form state -----
156	  const [companyName, setCompanyName] = useState("");
157	  const [slug, setSlug] = useState("");
158	  const [logoUrl, setLogoUrl] = useState("");
159	  const [brandColor, setBrandColor] = useState("#6366f1");
160	  const [tagline, setTagline] = useState("");
161	  const [about, setAbout] = useState("");
162	  const [isActive, setIsActive] = useState(false);
163	  const [configId, setConfigId] = useState<string | null>(null);
164	  const [isSaving, setIsSaving] = useState(false);
165	  const [slugStatus, setSlugStatus] = useState<SlugStatus>("idle");
166	  const [slugManuallyEdited, setSlugManuallyEdited] = useState(false);
167	  const [togglingJobId, setTogglingJobId] = useState<string | null>(null);
168	
169	  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
170	
171	  // ----- Career page URL -----
172	  const careerPageUrl = slug ? `${window.location.origin}/careers/${slug}` : null;
173	
174	  // ----- Fetch config -----
175	  const { data: configData, isLoading: configLoading } = useQuery({
176	    queryKey: ["career-page-config", teamId],
177	    queryFn: async () => {
178	      if (!teamId) return null;
179	      const { data, error } = await (supabase as any)
180	        .from("career_page_config")
181	        .select("*")
182	        .eq("team_id", teamId)
183	        .maybeSingle();
184	      if (error) throw new Error(error.message);
185	      return data as CareerPageConfig | null;
186	    },
187	    enabled: !!teamId,
188	    staleTime: 60_000,
189	  });
190	
191	  // Populate form when config loads
192	  useEffect(() => {
193	    if (configData) {
194	      setConfigId(configData.id);
195	      setCompanyName(configData.company_name ?? "");
196	      setSlug(configData.slug ?? "");
197	      setLogoUrl(configData.logo_url ?? "");
198	      setBrandColor(configData.brand_color ?? "#6366f1");
199	      setTagline(configData.tagline ?? "");
200	      setAbout(configData.about ?? "");
201	      setIsActive(configData.is_active ?? false);
202	      setSlugManuallyEdited(true); // Don't auto-overwrite on subsequent renders
203	    } else if (!configLoading && team?.name) {
204	      // Pre-fill from team name on first load
205	      setCompanyName(team.name);
206	      const auto = slugify(team.name);
207	      setSlug(auto);
208	    }
209	  }, [configData, configLoading, team?.name]);
210	
211	  // ----- Fetch jobs -----
212	  const { data: jobs = [], isLoading: jobsLoading } = useQuery({
213	    queryKey: ["career-jobs", userId],
214	    queryFn: async () => {
215	      if (!userId) return [];
216	      const { data, error } = await (supabase as any)
217	        .from("jobs")
218	        .select("id, title, location, department, employment_type, is_published, status, view_count, apply_count")
219	        .eq("user_id", userId)
220	        .order("created_at", { ascending: false });
221	      if (error) throw new Error(error.message);
222	      return (data ?? []) as CareerJob[];
223	    },
224	    enabled: !!userId,
225	    staleTime: 30_000,
226	  });
227	
228	  // ----- Slug auto-gen from company name -----
229	  const handleCompanyNameChange = (value: string) => {
230	    setCompanyName(value);
231	    if (!slugManuallyEdited) {
232	      const auto = slugify(value);
233	      setSlug(auto);
234	      triggerSlugCheck(auto);
235	    }
236	  };
237	
238	  // ----- Slug check debounce -----
239	  const triggerSlugCheck = useCallback(
240	    (value: string) => {
241	      if (debounceRef.current) clearTimeout(debounceRef.current);
242	      if (!value || !teamId) {
243	        setSlugStatus("idle");
244	        return;
245	      }
246	      setSlugStatus("checking");
247	      debounceRef.current = setTimeout(async () => {
248	        try {
249	          const { data, error } = await (supabase as any).rpc("is_career_slug_available", {
250	            p_slug: value,
251	            p_team_id: teamId,
252	          });
253	          if (error) throw error;
254	          setSlugStatus(data === true ? "available" : "taken");
255	        } catch {
256	          setSlugStatus("idle");
257	        }
258	      }, 600);
259	    },
260	    [teamId]
261	  );
262	
263	  const handleSlugChange = (value: string) => {
264	    const clean = value.toLowerCase().replace(/[^a-z0-9-]/g, "").slice(0, 60);
265	    setSlug(clean);
266	    setSlugManuallyEdited(true);
267	    triggerSlugCheck(clean);
268	  };
269	
270	  // Cleanup debounce on unmount
271	  useEffect(() => {
272	    return () => {
273	      if (debounceRef.current) clearTimeout(debounceRef.current);
274	    };
275	  }, []);
276	
277	  // ----- Save config -----
278	  const handleSave = async () => {
279	    if (!teamId) {
280	      toast.error("No team found. Create a team first.");
281	      return;
282	    }
283	    if (!companyName.trim()) {
284	      toast.error("Company name is required.");
285	      return;
286	    }
287	    if (!slug.trim()) {
288	      toast.error("URL slug is required.");
289	      return;
290	    }
291	    // DB constraint: ^[a-z0-9][a-z0-9\-]{1,58}[a-z0-9]$ — minimum 3 chars, must start/end with alphanumeric
292	    if (slug.length < 3) {
293	      toast.error("Slug must be at least 3 characters.");
294	      return;
295	    }
296	    if (!/^[a-z0-9]/.test(slug) || !/[a-z0-9]$/.test(slug)) {
297	      toast.error("Slug must start and end with a letter or number.");
298	      return;
299	    }
300	    if (slugStatus === "taken") {
301	      toast.error("That slug is already taken. Choose a different one.");
302	      return;
303	    }
304	
305	    setIsSaving(true);
306	    try {
307	      const payload = {
308	        team_id: teamId,
309	        company_name: companyName.trim(),
310	        slug: slug.trim(),
311	        logo_url: logoUrl.trim() || null,
312	        brand_color: isValidHex(brandColor) ? brandColor : "#6366f1",
313	        tagline: tagline.trim() || null,
314	        about: about.trim() || null,
315	        is_active: isActive,
316	      };
317	
318	      if (configId) {
319	        const { error } = await (supabase as any)
320	          .from("career_page_config")
321	          .update(payload)
322	          .eq("id", configId);
323	        if (error) throw error;
324	      } else {
325	        const { data: inserted, error } = await (supabase as any)
326	          .from("career_page_config")
327	          .insert(payload)
328	          .select("id")
329	          .single();
330	        if (error) throw error;
331	        // Capture the new row id so subsequent saves use UPDATE, not INSERT.
332	        // Without this, a second save attempt would hit the UNIQUE(team_id) constraint.
333	        if (inserted?.id) {
334	          setConfigId(inserted.id as string);
335	        }
336	      }
337	
338	      toast.success("Career page saved");
339	      queryClient.invalidateQueries({ queryKey: ["career-page-config", teamId] });
340	    } catch (err: unknown) {
341	      const msg = err instanceof Error ? err.message : "Failed to save career page";
342	      toast.error(msg);
343	    } finally {
344	      setIsSaving(false);
345	    }
346	  };
347	
348	  // ----- Toggle job published -----
349	  const toggleJobPublished = useMutation({
350	    mutationFn: async ({ jobId, current }: { jobId: string; current: boolean }) => {
351	      const { error } = await (supabase as any)
352	        .from("jobs")
353	        .update({ is_published: !current })
354	        .eq("id", jobId);
355	      if (error) throw new Error(error.message);
356	      return { jobId, newValue: !current };
357	    },
358	    onMutate: ({ jobId }) => {
359	      setTogglingJobId(jobId);
360	    },
361	    onSuccess: ({ jobId, newValue }) => {
362	      queryClient.setQueryData(["career-jobs", userId], (old: CareerJob[] | undefined) =>
363	        (old ?? []).map((j) => (j.id === jobId ? { ...j, is_published: newValue } : j))
364	      );
365	      toast.success(newValue ? "Job published to career page" : "Job unpublished");
366	    },
367	    onError: (err: unknown) => {
368	      const msg = err instanceof Error ? err.message : "Failed to update job";
369	      toast.error(msg);
370	    },
371	    onSettled: () => {
372	      setTogglingJobId(null);
373	    },
374	  });
375	
376	  // ----- Clipboard copy -----
377	  function copyUrl() {
378	    if (!careerPageUrl) return;
379	    navigator.clipboard.writeText(careerPageUrl).then(
380	      () => toast.success("Link copied"),
381	      () => toast.error("Could not copy link")
382	    );
383	  }
384	
385	  // ---------------------------------------------------------------------------
386	  // Render
387	  // ---------------------------------------------------------------------------
388	
389	  return (
390	    <SidebarLayout>
391	      <main className="w-full max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
392	        <div className="flex items-start justify-between mb-1">
393	          <h1 className="text-2xl font-bold text-foreground">Career Page</h1>
394	          {isActive && careerPageUrl && (
395	            <div className="flex items-center gap-1.5">
396	              <Badge variant="outline" className="text-xs border-green-500/50 text-green-600 dark:text-green-400 gap-1">
397	                <Eye className="h-3 w-3" />
398	                Live
399	              </Badge>
400	              <Button
401	                variant="ghost"
402	                size="icon"
403	                className="h-7 w-7"
404	                onClick={copyUrl}
405	                aria-label="Copy career page URL"
406	              >
407	                <Copy className="h-3.5 w-3.5" />
408	              </Button>
409	              <Button
410	                variant="ghost"
411	                size="icon"
412	                className="h-7 w-7"
413	                onClick={() => window.open(careerPageUrl, "_blank")}
414	                aria-label="Open career page"
415	              >
416	                <ExternalLink className="h-3.5 w-3.5" />
417	              </Button>
418	            </div>
419	          )}
420	        </div>
421	        <p className="text-sm text-muted-foreground mb-6">
422	          Customize your public career page and manage which jobs are visible to candidates.
423	        </p>
424	
425	        <div className="space-y-6">
426	          {/* ---------------------------------------------------------------- */}
427	          {/* Card 1: Configuration                                             */}
428	          {/* ---------------------------------------------------------------- */}
429	          <Card className="border border-border/60 shadow-sm">
430	            <CardHeader className="pb-3">
431	              <CardTitle className="text-sm font-semibold flex items-center gap-2">
432	                <Globe className="h-4 w-4 text-primary" />
433	                Career Page Configuration
434	              </CardTitle>
435	              <CardDescription className="text-xs">
436	                Set up your branded career page. Share the link with candidates.
437	              </CardDescription>
438	            </CardHeader>
439	            <CardContent>
440	              {configLoading ? (
441	                <ConfigSkeleton />
442	              ) : (
443	                <div className="space-y-5">
444	                  {/* Company name */}
445	                  <div className="space-y-1.5">
446	                    <Label htmlFor="company-name" className="text-xs font-medium">
447	                      Company name
448	                    </Label>
449	                    <Input
450	                      id="company-name"
451	                      placeholder="Acme Corp"
452	                      value={companyName}
453	                      onChange={(e) => handleCompanyNameChange(e.target.value)}
454	                      disabled={isSaving}
455	                    />
456	                  </div>
457	
458	                  {/* Slug */}
459	                  <div className="space-y-1.5">
460	                    <div className="flex items-center justify-between">
461	                      <Label htmlFor="slug" className="text-xs font-medium">
462	                        URL slug
463	                      </Label>
464	                      <SlugStatusBadge status={slugStatus} />
465	                    </div>
466	                    <div className="flex items-center rounded-md border border-input bg-background ring-offset-background focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-2 overflow-hidden">
467	                      <span className="flex items-center pl-3 pr-1 text-xs text-muted-foreground whitespace-nowrap shrink-0 select-none">
468	                        /careers/
469	                      </span>
470	                      <input
471	                        id="slug"
472	                        className="flex-1 py-2 pr-3 text-sm bg-transparent outline-none placeholder:text-muted-foreground"
473	                        placeholder="acme-corp"
474	                        value={slug}
475	                        onChange={(e) => handleSlugChange(e.target.value)}
476	                        disabled={isSaving}
477	                        spellCheck={false}
478	                        aria-describedby="slug-hint"
479	                      />
480	                    </div>
481	                    <p id="slug-hint" className="text-xs text-muted-foreground">
482	                      Lowercase letters, numbers, and hyphens only.
483	                    </p>
484	                  </div>
485	
486	                  {/* Logo URL */}
487	                  <div className="space-y-1.5">
488	                    <Label htmlFor="logo-url" className="text-xs font-medium">
489	                      Logo URL
490	                    </Label>
491	                    <Input
492	                      id="logo-url"
493	                      placeholder="https://example.com/logo.png"
494	                      value={logoUrl}
495	                      onChange={(e) => setLogoUrl(e.target.value)}
496	                      disabled={isSaving}
497	                      type="url"
498	                    />
499	                  </div>
500	
501	                  {/* Brand color */}
502	                  <div className="space-y-1.5">
503	                    <Label className="text-xs font-medium">Brand color</Label>
504	                    <div className="flex items-center gap-2">
505	                      <div className="relative h-9 w-14 shrink-0">
506	                        <input
507	                          type="color"
508	                          className="absolute inset-0 h-full w-full cursor-pointer rounded-md border border-input opacity-0"
509	                          value={isValidHex(brandColor) ? brandColor : "#6366f1"}
510	                          onChange={(e) => setBrandColor(e.target.value)}
511	                          disabled={isSaving}
512	                          aria-label="Pick brand color"
513	                        />
514	                        <div
515	                          className="h-full w-full rounded-md border border-input"
516	                          style={{ backgroundColor: isValidHex(brandColor) ? brandColor : "#6366f1" }}
517	                        />
518	                      </div>
519	                      <Input
520	                        placeholder="#6366f1"
521	                        value={brandColor}
522	                        onChange={(e) => setBrandColor(e.target.value)}
523	                        disabled={isSaving}
524	                        className="font-mono text-sm w-32"
525	                        maxLength={7}
526	                        aria-label="Brand color hex code"
527	                      />
528	                      {!isValidHex(brandColor) && brandColor.length > 0 && (
529	                        <span className="text-xs text-destructive">Use 6-digit hex (e.g. #6366f1)</span>
530	                      )}
531	                    </div>
532	                  </div>
533	
534	                  {/* Tagline */}
535	                  <div className="space-y-1.5">
536	                    <Label htmlFor="tagline" className="text-xs font-medium">
537	                      Tagline
538	                    </Label>
539	                    <Input
540	                      id="tagline"
541	                      placeholder="We're building the future of work"
542	                      value={tagline}
543	                      onChange={(e) => setTagline(e.target.value)}
544	                      disabled={isSaving}
545	                      maxLength={160}
546	                    />
547	                  </div>
548	
549	                  {/* About */}
550	                  <div className="space-y-1.5">
551	                    <Label htmlFor="about" className="text-xs font-medium">
552	                      About
553	                    </Label>
554	                    <Textarea
555	                      id="about"
556	                      placeholder="Tell candidates about your company, culture, and mission…"
557	                      value={about}
558	                      onChange={(e) => setAbout(e.target.value)}
559	                      disabled={isSaving}
560	                      rows={4}
561	                      className="resize-none text-sm"
562	                      maxLength={2000}
563	                    />
564	                  </div>
565	
566	                  {/* Active toggle */}
567	                  <div className="flex items-center justify-between rounded-lg border border-border p-3">
568	                    <div className="space-y-0.5">
569	                      <Label htmlFor="is-active" className="text-sm font-medium cursor-pointer">
570	                        Publish career page
571	                      </Label>
572	                      <p className="text-xs text-muted-foreground">
573	                        Make your career page publicly accessible to candidates.
574	                      </p>
575	                    </div>
576	                    <Switch
577	                      id="is-active"
578	                      checked={isActive}
579	                      onCheckedChange={setIsActive}
580	                      disabled={isSaving}
581	                      aria-label="Publish career page"
582	                    />
583	                  </div>
584	
585	                  {/* Preview link (when active + slug set) */}
586	                  {isActive && careerPageUrl && (
587	                    <div className="flex items-center gap-2 rounded-md bg-muted/50 px-3 py-2">
588	                      <Globe className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
589	                      <a
590	                        href={careerPageUrl}
591	                        target="_blank"
592	                        rel="noopener noreferrer"
593	                        className="flex-1 text-xs text-primary truncate hover:underline"
594	                      >
595	                        {careerPageUrl}
596	                      </a>
597	                      <button
598	                        onClick={copyUrl}
599	                        className="shrink-0 text-muted-foreground hover:text-foreground transition-colors"
600	                        aria-label="Copy career page URL"
601	                        type="button"
602	                      >
603	                        <Copy className="h-3.5 w-3.5" />
604	                      </button>
605	                      <a
606	                        href={careerPageUrl}
607	                        target="_blank"
608	                        rel="noopener noreferrer"
609	                        className="shrink-0 text-muted-foreground hover:text-foreground transition-colors"
610	                        aria-label="Open in new tab"
611	                      >
612	                        <ExternalLink className="h-3.5 w-3.5" />
613	                      </a>
614	                    </div>
615	                  )}
616	
617	                  {/* Save button */}
618	                  <div className="flex justify-end pt-1">
619	                    <Button
620	                      onClick={handleSave}
621	                      disabled={isSaving || slugStatus === "taken"}
622	                      className="gap-1.5"
623	                    >
624	                      {isSaving ? (
625	                        <Loader2 className="h-4 w-4 animate-spin" />
626	                      ) : (
627	                        <Save className="h-4 w-4" />
628	                      )}
629	                      Save changes
630	                    </Button>
631	                  </div>
632	                </div>
633	              )}
634	            </CardContent>
635	          </Card>
636	
637	          {/* ---------------------------------------------------------------- */}
638	          {/* Card 2: Published Jobs                                            */}
639	          {/* ---------------------------------------------------------------- */}
640	          <Card className="border border-border/60 shadow-sm">
641	            <CardHeader className="pb-3">
642	              <CardTitle className="text-sm font-semibold flex items-center gap-2">
643	                <Globe className="h-4 w-4 text-primary" />
644	                Published Jobs
645	              </CardTitle>
646	              <CardDescription className="text-xs">
647	                Toggle which jobs appear on your career page.
648	              </CardDescription>
649	            </CardHeader>
650	            <CardContent className="p-0">
651	              {jobsLoading ? (
652	                <JobsSkeleton />
653	              ) : jobs.length === 0 ? (
654	                <div className="flex flex-col items-center justify-center py-14 space-y-3 text-center px-4">
655	                  <div className="rounded-xl bg-muted/50 p-4">
656	                    <Globe className="h-7 w-7 text-muted-foreground/40" />
657	                  </div>
658	                  <div className="space-y-1">
659	                    <p className="text-sm font-medium text-foreground">No jobs yet</p>
660	                    <p className="text-sm text-muted-foreground max-w-xs">
661	                      Create a job posting from the dashboard to list it on your career page.
662	                    </p>
663	                  </div>
664	                </div>
665	              ) : (
666	                <Table>
667	                  <TableHeader>
668	                    <TableRow>
669	                      <TableHead className="text-xs">Title</TableHead>
670	                      <TableHead className="text-xs hidden sm:table-cell">Location</TableHead>
671	                      <TableHead className="text-xs hidden md:table-cell">Department</TableHead>
672	                      <TableHead className="text-xs hidden lg:table-cell">Analytics</TableHead>
673	                      <TableHead className="text-xs text-right pr-4">Published</TableHead>
674	                    </TableRow>
675	                  </TableHeader>
676	                  <TableBody>
677	                    {jobs.map((job) => {
678	                      const isToggling = togglingJobId === job.id;
679	                      const published = job.is_published ?? false;
680	                      return (
681	                        <TableRow key={job.id}>
682	                          <TableCell className="text-sm font-medium max-w-[200px]">
683	                            <div className="truncate" title={job.title ?? ""}>
684	                              {job.title || <span className="text-muted-foreground italic">Untitled</span>}
685	                            </div>
686	                            {job.employment_type && (
687	                              <span className="text-xs text-muted-foreground">{job.employment_type}</span>
688	                            )}
689	                          </TableCell>
690	                          <TableCell className="text-sm text-muted-foreground hidden sm:table-cell">
691	                            {job.location || "—"}
692	                          </TableCell>
693	                          <TableCell className="text-sm text-muted-foreground hidden md:table-cell">
694	                            {job.department || "—"}
695	                          </TableCell>
696	                          <TableCell className="hidden lg:table-cell">
697	                            <span className="text-xs text-muted-foreground whitespace-nowrap">
698	                              {(job.view_count ?? 0).toLocaleString()} views
699	                              {" · "}
700	                              {(job.apply_count ?? 0).toLocaleString()} applied
701	                            </span>
702	                          </TableCell>
703	                          <TableCell className="text-right pr-4">
704	                            {isToggling ? (
705	                              <div className="flex justify-end">
706	                                <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
707	                              </div>
708	                            ) : (
709	                              <Switch
710	                                checked={published}
711	                                onCheckedChange={() =>
712	                                  toggleJobPublished.mutate({ jobId: job.id, current: published })
713	                                }
714	                                disabled={isToggling}
715	                                aria-label={`${published ? "Unpublish" : "Publish"} ${job.title ?? "job"}`}
716	                              />
717	                            )}
718	                          </TableCell>
719	                        </TableRow>
720	                      );
721	                    })}
722	                  </TableBody>
723	                </Table>
724	              )}
725	            </CardContent>
726	          </Card>
727	        </div>
728	      </main>
729	    </SidebarLayout>
730	  );
731	};
732	
733	export default CareerSettings;
