                              <span className={`text-xs ${isExpired ? "text-destructive" : "text-muted-foreground"}`}>
                                {isExpired ? "Expired" : new Date(job.expires_at).toLocaleDateString()}
                              </span>
                            ) : (
                              <span className="text-xs text-muted-foreground">—</span>
                            )}
                          </TableCell>
                          <TableCell className="hidden lg:table-cell">
                            <span className="text-xs text-muted-foreground whitespace-nowrap">
                              {(job.view_count ?? 0).toLocaleString()} views
                              {" · "}
                              {(job.apply_count ?? 0).toLocaleString()} applied
                            </span>
                          </TableCell>
                          <TableCell className="text-right pr-4">
                            {isToggling ? (
                              <div className="flex justify-end">
                                <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
                              </div>
                            ) : (
                              <Switch
                                checked={published}
                                onCheckedChange={() =>
                                  toggleJobPublished.mutate({ jobId: job.id, current: published })
                                }
                                disabled={isToggling}
                                aria-label={`${published ? "Unpublish" : "Publish"} ${job.title ?? "job"}`}
                              />
                            )}
                          </TableCell>
                        </TableRow>
                      );
                    })}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </div>
      </main>
    </SidebarLayout>
  );
};

export default CareerSettings;

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { MapPin, Building2, Clock, DollarSign, Share2, Linkedin, Twitter, Link2, Star, Sparkles } from "lucide-react";
import { formatDistanceToNow, differenceInDays } from "date-fns";
import { toast } from "sonner";

interface JobListingCardProps {
  id: string;
  title: string;
  location: string | null;
  department: string | null;
  employmentType: string | null;
  salaryRange: string | null;
  createdAt: string;
  brandColor: string;
  onApply: (jobId: string) => void;
  // Lifecycle props
  expiresAt?: string | null;
  isFeatured?: boolean;
}

/** Returns true if the date is within `days` days from now */
function isWithinDays(dateStr: string, days: number): boolean {
  const diff = differenceInDays(new Date(dateStr), new Date());
  return diff >= 0 && diff <= days;
}

/** Returns true if the date is within 3 days ago (i.e. posted recently) */
function isRecentlyPosted(dateStr: string): boolean {
  const diff = differenceInDays(new Date(), new Date(dateStr));
  return diff <= 3;
}

export default function JobListingCard({
  id,
  title,
  location,
  department,
  employmentType,
  salaryRange,
  createdAt,
  brandColor,
  onApply,
  expiresAt,
  isFeatured,
}: JobListingCardProps) {
  const metadata = [
    location && { icon: MapPin, text: location },
    department && { icon: Building2, text: department },
    employmentType && { icon: Clock, text: employmentType },
    salaryRange && { icon: DollarSign, text: salaryRange },
  ].filter(Boolean) as { icon: typeof MapPin; text: string }[];

  const closingSoon = expiresAt ? isWithinDays(expiresAt, 7) : false;
  const isNew = isRecentlyPosted(createdAt);

  return (
    <Card
      className={`group hover:shadow-md transition-shadow duration-200 border border-border ${isFeatured ? "ring-1 ring-primary/20" : ""}`}
    >
      <CardContent className="p-5">
        <div className="flex items-start justify-between gap-4">
          <div className="space-y-2 min-w-0 flex-1">
            {/* Title + lifecycle badges */}
            <div className="flex flex-wrap items-center gap-2">
              <h3 className="text-lg font-semibold text-foreground leading-tight">
                {title || "Untitled Position"}
              </h3>
              {isFeatured && (
                <Badge
                  variant="secondary"
                  className="text-xs gap-1 shrink-0"
                  style={{ borderColor: brandColor + "40", color: brandColor }}
                >
                  <Star className="h-3 w-3 fill-current" />
                  Featured
                </Badge>
              )}
              {isNew && !isFeatured && (
                <Badge variant="secondary" className="text-xs gap-1 shrink-0 bg-green-50 text-green-700 dark:bg-green-950/30 dark:text-green-400 border-green-200 dark:border-green-800/40">
                  <Sparkles className="h-3 w-3" />
                  New
                </Badge>
              )}
              {closingSoon && (
                <Badge variant="outline" className="text-xs gap-1 shrink-0 border-amber-500/40 text-amber-600 dark:text-amber-400">
                  <Clock className="h-3 w-3" />
                  Closing Soon
                </Badge>
              )}
            </div>

            {/* Metadata row */}
            {metadata.length > 0 && (
              <div className="flex flex-wrap items-center gap-x-4 gap-y-1">
                {metadata.map((m, i) => (
                  <span
                    key={i}
                    className="flex items-center gap-1 text-sm text-muted-foreground"
                  >
                    <m.icon className="h-3.5 w-3.5 shrink-0" />
                    {m.text}
                  </span>
                ))}
              </div>
            )}

            {/* Posted + share row */}
            <div className="flex items-center gap-3">
              <p className="text-xs text-muted-foreground/60">
                Posted {formatDistanceToNow(new Date(createdAt), { addSuffix: true })}
              </p>
              {/* Social sharing */}
              <TooltipProvider>
                <div className="flex items-center gap-0.5">
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          const url = `${window.location.origin}/apply/${id}`;
                          window.open(
                            `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(url)}`,
                            "_blank",
                            "noopener,noreferrer,width=600,height=500"
                          );
                        }}
                        className="h-6 w-6 rounded flex items-center justify-center text-muted-foreground/40 hover:text-[#0A66C2] transition-colors"
                      >
                        <Linkedin className="h-3 w-3" />
                      </button>
                    </TooltipTrigger>
                    <TooltipContent>Share on LinkedIn</TooltipContent>
                  </Tooltip>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          const url = `${window.location.origin}/apply/${id}`;
                          const text = `${title || "Check out this position"}`;
                          window.open(
                            `https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(url)}`,
                            "_blank",
                            "noopener,noreferrer,width=600,height=400"
                          );
                        }}
                        className="h-6 w-6 rounded flex items-center justify-center text-muted-foreground/40 hover:text-foreground transition-colors"
                      >
                        <Twitter className="h-3 w-3" />
                      </button>
                    </TooltipTrigger>
                    <TooltipContent>Share on X</TooltipContent>
                  </Tooltip>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          const url = `${window.location.origin}/apply/${id}`;
                          navigator.clipboard.writeText(url);
                          toast.success("Link copied");
                        }}
                        className="h-6 w-6 rounded flex items-center justify-center text-muted-foreground/40 hover:text-foreground transition-colors"
                      >
                        <Link2 className="h-3 w-3" />
                      </button>
                    </TooltipTrigger>
                    <TooltipContent>Copy link</TooltipContent>
                  </Tooltip>
                </div>
              </TooltipProvider>
            </div>
          </div>

          <Button
            className="shrink-0 text-white hover:opacity-90"
            style={{ backgroundColor: brandColor }}
            onClick={() => onApply(id)}
          >
            Apply Now
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

