import { useState, useEffect } from "react";
import { useParams, useNavigate, Link } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Skeleton } from "@/components/ui/skeleton";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Briefcase, Layers, Search, Globe, Linkedin, Twitter, Instagram, Facebook, Bell } from "lucide-react";
import JobListingCard from "@/components/career/JobListingCard";
import { toast } from "sonner";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface Benefit {
  icon: string;
  title: string;
  description: string;
}

interface SocialLinks {
  website?: string;
  linkedin?: string;
  twitter?: string;
  instagram?: string;
  facebook?: string;
}

interface CareerConfig {
  company_name: string;
  logo_url: string | null;
  brand_color: string;
  tagline: string | null;
  about: string | null;
  // Enhanced
  custom_css: string | null;
  cover_image_url: string | null;
  culture_title: string | null;
  culture_description: string | null;
  benefits: Benefit[] | null;
  social_links: SocialLinks | null;
  meta_description: string | null;
  meta_keywords: string | null;
}

interface CareerJob {
  id: string;
  title: string;
  location: string | null;
  department: string | null;
  employment_type: string | null;
  salary_range: string | null;
  created_at: string;
  expires_at: string | null;
  is_featured: boolean | null;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Resolve a Lucide icon name to a Unicode emoji fallback for the benefits grid */
const iconFallbacks: Record<string, string> = {
  Heart: "❤️", Star: "⭐", Zap: "⚡", Globe: "🌍", Shield: "🛡️",
  Award: "🏆", Coffee: "☕", Users: "👥", TrendingUp: "📈", Home: "🏠",
  Smile: "😊", Clock: "⏰", DollarSign: "💰", Gift: "🎁", Briefcase: "💼",
  Laptop: "💻", Plane: "✈️", BookOpen: "📚", Music: "🎵", Camera: "📷",
};

function BenefitIcon({ name }: { name: string }) {
  const emoji = iconFallbacks[name] ?? "✦";
  return <span className="text-2xl leading-none" role="img" aria-label={name}>{emoji}</span>;
}

// ---------------------------------------------------------------------------
// Subscribe form
// ---------------------------------------------------------------------------

function SubscribeSection({ teamId, brandColor }: { teamId: string; brandColor: string }) {
  const [email, setEmail] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [subscribed, setSubscribed] = useState(false);

  const handleSubscribe = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email.trim() || !teamId) return;
    setSubmitting(true);
    try {
      const { error } = await (supabase as any)
        .from("career_subscribers")
        .insert({ team_id: teamId, email: email.trim().toLowerCase() });
      if (error) {
        if (error.code === "23505") {
          // Unique constraint — already subscribed
          toast.info("You're already subscribed to job alerts.");
        } else {
          throw error;
        }
      } else {
        setSubscribed(true);
        toast.success("Subscribed! We'll notify you about new positions.");
      }
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Failed to subscribe";
      toast.error(msg);
    } finally {
      setSubmitting(false);
    }
  };

  if (subscribed) {
    return (
      <section className="py-12 border-t border-border bg-muted/30">
        <div className="max-w-md mx-auto text-center px-4 space-y-2">
          <Bell className="h-8 w-8 mx-auto text-primary" />
          <h3 className="text-base font-semibold">You're subscribed</h3>
          <p className="text-sm text-muted-foreground">
            We'll email you when new positions are posted.
          </p>
        </div>
      </section>
    );
  }

  return (
    <section className="py-12 border-t border-border bg-muted/30">
      <div className="max-w-md mx-auto text-center px-4">
        <Bell className="h-7 w-7 mx-auto text-muted-foreground mb-3" />
        <h3 className="text-lg font-semibold mb-2">Get notified about new positions</h3>
        <p className="text-sm text-muted-foreground mb-4">
          Enter your email and we'll send you updates when new jobs are posted.
        </p>
        <form className="flex gap-2" onSubmit={handleSubscribe}>
          <Input
            type="email"
            placeholder="your@email.com"
            required
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            disabled={submitting}
            className="flex-1"
          />
          <Button
            type="submit"
            disabled={submitting || !email.trim()}
            style={{ backgroundColor: brandColor }}
            className="text-white hover:opacity-90 shrink-0"
          >
            {submitting ? "Subscribing…" : "Subscribe"}
          </Button>
        </form>
      </div>
    </section>
  );
}

// ---------------------------------------------------------------------------
// Main page
// ---------------------------------------------------------------------------

export default function CareerPage() {
  const { slug } = useParams<{ slug: string }>();
  const navigate = useNavigate();
  const [selectedDept, setSelectedDept] = useState<string | null>(null);
  const [selectedLocation, setSelectedLocation] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");

  const { data, isLoading } = useQuery({
    queryKey: ["career-page", slug],
    queryFn: async () => {
      if (!slug) return null;
      const { data, error } = await supabase.rpc("get_career_page", {
        p_slug: slug,
      });
      if (error) throw error;
      return data as { config: CareerConfig; jobs: CareerJob[]; team_id?: string } | null;
    },
    enabled: !!slug,
    staleTime: 60_000,
  });

  const config = data?.config;
  // The RPC now returns team_id in the top-level object so SubscribeSection can use it.
  // If not present (older version), fall back gracefully.
  const teamId: string = (data as any)?.team_id ?? "";
  const jobs = data?.jobs ?? [];
  const brandColor = config?.brand_color ?? "#6366f1";
  const benefits = Array.isArray(config?.benefits) ? (config!.benefits as Benefit[]) : [];
  const socialLinks = (config?.social_links ?? {}) as SocialLinks;

  const departments = [...new Set(jobs.map((j) => j.department).filter(Boolean))] as string[];
  const locations = [...new Set(jobs.map((j) => j.location).filter(Boolean))] as string[];

  const filteredJobs = jobs.filter((j) => {
    if (selectedDept && j.department !== selectedDept) return false;
    if (selectedLocation && j.location !== selectedLocation) return false;
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      const match =
        (j.title ?? "").toLowerCase().includes(q) ||
        (j.department ?? "").toLowerCase().includes(q) ||
        (j.location ?? "").toLowerCase().includes(q);
      if (!match) return false;
    }
    return true;
  });

  // Featured jobs first, then rest
  const featuredJobs = filteredJobs.filter((j) => j.is_featured);
  const regularJobs = filteredJobs.filter((j) => !j.is_featured);

  useEffect(() => {
    if (config) {
      document.title = `Careers at ${config.company_name} | Rankora`;
      if (config.meta_description) {
        let tag = document.querySelector<HTMLMetaElement>('meta[name="description"]');
        if (!tag) {
          tag = document.createElement("meta");
          tag.name = "description";
          document.head.appendChild(tag);
        }
        tag.content = config.meta_description;
      }
    }
    return () => {
      document.title = "Rankora";
      const tag = document.querySelector<HTMLMetaElement>('meta[name="description"]');
      if (tag) tag.content = "";
    };
  }, [config]);

  const handleApply = (jobId: string) => navigate(`/apply/${jobId}`);

  // Social link helpers
  const hasSocialLinks = Object.values(socialLinks).some(Boolean);

  // Loading
  if (isLoading) {
    return (
      <div className="min-h-screen bg-background flex flex-col">
        <header className="border-b border-border">
          <div className="max-w-4xl mx-auto px-4 py-4 flex items-center gap-3">
            <Skeleton className="h-8 w-8 rounded" />
            <Skeleton className="h-5 w-32" />
          </div>
        </header>
        <div className="max-w-4xl mx-auto px-4 py-12 w-full space-y-4">
          <Skeleton className="h-8 w-64 mx-auto" />
          <Skeleton className="h-4 w-48 mx-auto" />
          <div className="space-y-4 mt-8">
            {[1, 2, 3].map((i) => (
              <Skeleton key={i} className="h-24 w-full rounded-xl" />
            ))}
          </div>
        </div>
      </div>
    );
  }

  // Not found
  if (!config) {
    return (
      <div className="min-h-screen bg-background flex flex-col">
        <header className="border-b border-border">
          <div className="max-w-4xl mx-auto px-4 py-4">
            <Link to="/" className="flex items-center gap-2 text-sm font-semibold">
              <Layers className="h-5 w-5 text-primary" /> Rankora
            </Link>
          </div>
        </header>
        <main className="flex-1 flex items-center justify-center px-4 py-16">
          <div className="text-center space-y-4">
            <div className="w-14 h-14 rounded-full bg-muted flex items-center justify-center mx-auto">
              <Briefcase className="h-7 w-7 text-muted-foreground" />
            </div>
            <h1 className="text-xl font-semibold">Career page not found</h1>
            <p className="text-sm text-muted-foreground">
              This career page may have been removed or is not yet active.
            </p>
            <Link to="/" className="text-sm font-medium text-primary hover:text-primary/80 transition-colors">
              Back to Rankora
            </Link>
          </div>
        </main>
      </div>
    );
  }

  // Active career page
  return (
    <div className="min-h-screen bg-background flex flex-col">
      {/* Custom CSS injection */}
      {config.custom_css && (
        <style dangerouslySetInnerHTML={{ __html: config.custom_css }} />
      )}

      {/* Header */}
      <header className="sticky top-0 z-10 bg-background/95 backdrop-blur border-b border-border">
        <div className="max-w-4xl mx-auto px-4 py-4 flex items-center gap-3">
          {config.logo_url && (
            <img
              src={config.logo_url}
              alt={config.company_name}
              className="h-8 w-8 rounded object-cover"
            />
          )}
          <span className="font-semibold text-lg text-foreground">
            {config.company_name}
          </span>
        </div>
      </header>

      {/* Cover image */}
      {config.cover_image_url && (
        <div
          className="w-full h-48 sm:h-64 bg-cover bg-center"
          style={{ backgroundImage: `url(${config.cover_image_url})` }}
          role="img"
          aria-label={`${config.company_name} cover image`}
        />
      )}

      {/* Hero */}
      <div className="py-12 px-4" style={{ backgroundColor: brandColor + "0D" }}>
        <div className="max-w-4xl mx-auto text-center space-y-3">
