          {config.tagline && (
            <p className="text-lg text-muted-foreground">{config.tagline}</p>
          )}
          {config.about && (
            <p className="text-sm text-muted-foreground max-w-2xl mx-auto leading-relaxed mt-2">
              {config.about}
            </p>
          )}
          <Badge
            variant="secondary"
            className="mt-4 text-sm"
            style={{ borderColor: brandColor + "40" }}
          >
            {jobs.length} Open Position{jobs.length !== 1 ? "s" : ""}
          </Badge>
        </div>
      </div>

      {/* Search + Filters */}
      {jobs.length > 0 && (
        <div className="max-w-4xl mx-auto px-4 pt-6 space-y-3">
          {/* Search bar */}
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground pointer-events-none" />
            <Input
              placeholder="Search positions..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-9 h-10 bg-background"
            />
          </div>

          {/* Filter pills */}
          <div className="flex gap-4 flex-wrap">
            {departments.length > 1 && (
              <div className="flex gap-1.5 flex-wrap">
                <button
                  onClick={() => setSelectedDept(null)}
                  className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
                    !selectedDept ? "text-white" : "bg-muted text-muted-foreground hover:bg-muted/80"
                  }`}
                  style={!selectedDept ? { backgroundColor: brandColor } : undefined}
                >
                  All Depts
                </button>
                {departments.map((dept) => (
                  <button
                    key={dept}
                    onClick={() => setSelectedDept(dept)}
                    className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
                      selectedDept === dept ? "text-white" : "bg-muted text-muted-foreground hover:bg-muted/80"
                    }`}
                    style={selectedDept === dept ? { backgroundColor: brandColor } : undefined}
                  >
                    {dept}
                  </button>
                ))}
              </div>
            )}

            {locations.length > 1 && (
              <div className="flex gap-1.5 flex-wrap">
                <button
                  onClick={() => setSelectedLocation(null)}
                  className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
                    !selectedLocation ? "text-white" : "bg-muted text-muted-foreground hover:bg-muted/80"
                  }`}
                  style={!selectedLocation ? { backgroundColor: brandColor } : undefined}
                >
                  All Locations
                </button>
                {locations.map((loc) => (
                  <button
                    key={loc}
                    onClick={() => setSelectedLocation(loc)}
                    className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
                      selectedLocation === loc ? "text-white" : "bg-muted text-muted-foreground hover:bg-muted/80"
                    }`}
                    style={selectedLocation === loc ? { backgroundColor: brandColor } : undefined}
                  >
                    {loc}
                  </button>
                ))}
              </div>
            )}
          </div>

          {(searchQuery || selectedDept || selectedLocation) && (
            <p className="text-xs text-muted-foreground">
              {filteredJobs.length} position{filteredJobs.length !== 1 ? "s" : ""} found
            </p>
          )}
        </div>
      )}

      {/* Job listings */}
      <main className="flex-1 max-w-4xl mx-auto px-4 py-6 w-full">
        {filteredJobs.length === 0 ? (
          <div className="text-center py-16 space-y-3">
            <div className="w-14 h-14 rounded-full bg-muted flex items-center justify-center mx-auto">
              <Briefcase className="h-7 w-7 text-muted-foreground/40" />
            </div>
            <h2 className="text-base font-medium text-foreground">No open positions right now</h2>
            <p className="text-sm text-muted-foreground">Check back soon for new opportunities.</p>
          </div>
        ) : (
          <div className="space-y-6">
            {/* Featured jobs */}
            {featuredJobs.length > 0 && (
              <div className="space-y-3">
                <h2 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                  Featured Positions
                </h2>
                <div className="grid gap-4">
                  {featuredJobs.map((job) => (
                    <JobListingCard
                      key={job.id}
                      id={job.id}
                      title={job.title}
                      location={job.location}
                      department={job.department}
                      employmentType={job.employment_type}
                      salaryRange={job.salary_range}
                      createdAt={job.created_at}
                      brandColor={brandColor}
                      onApply={handleApply}
                      expiresAt={job.expires_at}
                      isFeatured={true}
                    />
                  ))}
                </div>
              </div>
            )}

            {/* Regular jobs */}
            {regularJobs.length > 0 && (
              <div className="space-y-3">
                {featuredJobs.length > 0 && (
                  <h2 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                    All Positions
                  </h2>
                )}
                <div className="grid gap-4">
                  {regularJobs.map((job) => (
                    <JobListingCard
                      key={job.id}
                      id={job.id}
                      title={job.title}
                      location={job.location}
                      department={job.department}
                      employmentType={job.employment_type}
                      salaryRange={job.salary_range}
                      createdAt={job.created_at}
                      brandColor={brandColor}
                      onApply={handleApply}
                      expiresAt={job.expires_at}
                      isFeatured={false}
                    />
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </main>

      {/* Culture & Benefits section */}
      {config.culture_description && (
        <section className="py-16 border-t border-border">
          <div className="max-w-4xl mx-auto px-4">
            <div className="text-center space-y-3 mb-10">
              <h2 className="text-2xl font-bold text-foreground">
                {config.culture_title || "Why Join Us"}
              </h2>
              <p className="text-muted-foreground max-w-2xl mx-auto leading-relaxed">
                {config.culture_description}
              </p>
            </div>
            {benefits.length > 0 && (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 mt-8">
                {benefits.map((benefit, i) => (
                  <div
                    key={i}
                    className="rounded-xl border border-border bg-card p-5 space-y-2 hover:shadow-sm transition-shadow"
                  >
                    <BenefitIcon name={benefit.icon} />
                    <h3 className="text-sm font-semibold text-foreground">{benefit.title}</h3>
                    {benefit.description && (
                      <p className="text-xs text-muted-foreground leading-relaxed">{benefit.description}</p>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        </section>
      )}

      {/* Email subscribe */}
      {teamId && <SubscribeSection teamId={teamId} brandColor={brandColor} />}

      {/* Footer */}
      <footer className="py-6 border-t border-border">
        <div className="max-w-4xl mx-auto px-4 space-y-4">
          {/* Social links */}
          {hasSocialLinks && (
            <div className="flex items-center justify-center gap-3">
              {socialLinks.website && (
                <a
                  href={socialLinks.website}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="text-muted-foreground hover:text-foreground transition-colors"
                  aria-label="Company website"
                >
                  <Globe className="h-4 w-4" />
                </a>
              )}
              {socialLinks.linkedin && (
                <a
                  href={socialLinks.linkedin}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="text-muted-foreground hover:text-[#0A66C2] transition-colors"
                  aria-label="LinkedIn"
                >
                  <Linkedin className="h-4 w-4" />
                </a>
              )}
              {socialLinks.twitter && (
                <a
                  href={socialLinks.twitter}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="text-muted-foreground hover:text-foreground transition-colors"
                  aria-label="X / Twitter"
                >
                  <Twitter className="h-4 w-4" />
                </a>
              )}
              {socialLinks.instagram && (
                <a
                  href={socialLinks.instagram}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="text-muted-foreground hover:text-[#E1306C] transition-colors"
                  aria-label="Instagram"
                >
                  <Instagram className="h-4 w-4" />
                </a>
              )}
              {socialLinks.facebook && (
                <a
                  href={socialLinks.facebook}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="text-muted-foreground hover:text-[#1877F2] transition-colors"
                  aria-label="Facebook"
                >
                  <Facebook className="h-4 w-4" />
                </a>
              )}
            </div>
          )}

          <div className="text-center space-y-2">
            <p className="text-xs text-muted-foreground">
              Powered by{" "}
              <Link to="/" className="text-primary font-medium hover:text-primary/80 transition-colors">
                Rankora
              </Link>
            </p>
            <p className="text-[10px] text-muted-foreground/50 max-w-md mx-auto">
              By applying, you agree that your information will be processed by the hiring company for recruitment purposes.
            </p>
          </div>
        </div>
      </footer>
    </div>
  );
}

