function JobMetadataSection({ jobId }: { jobId: string }) {
  const [open, setOpen] = useState(false);
  const [location, setLocation] = useState("");
  const [department, setDepartment] = useState("");
  const [employmentType, setEmploymentType] = useState("Full-time");
  const [salaryRange, setSalaryRange] = useState("");
  const [saving, setSaving] = useState(false);
  // loaded tracks whether DB data has been fetched — blocks form render until then
  // to prevent user input being silently overwritten by the async load.
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    // Reset loaded state when job changes so we don't show stale data
    setLoaded(false);
    setLocation("");
    setDepartment("");
    setEmploymentType("Full-time");
    setSalaryRange("");

    let cancelled = false;
    (async () => {
      const { data } = await (supabase as any)
        .from("jobs")
        .select("location, department, employment_type, salary_range")
        .eq("id", jobId)
        .single();
      if (!cancelled) {
        setLocation(data?.location ?? "");
        setDepartment(data?.department ?? "");
        setEmploymentType(data?.employment_type ?? "Full-time");
        setSalaryRange(data?.salary_range ?? "");
        setLoaded(true);
      }
    })();
    return () => { cancelled = true; };
  }, [jobId]);

  const handleSave = async () => {
    setSaving(true);
    try {
      const { error } = await (supabase as any)
        .from("jobs")
        .update({
          location: location.trim() || null,
          department: department.trim() || null,
          employment_type: employmentType,
          salary_range: salaryRange.trim() || null,
        })
        .eq("id", jobId);
      if (error) throw error;
      toast.success("Job details saved");
    } catch {
      toast.error("Failed to save job details");
    } finally {
      setSaving(false);
    }
  };

  return (
    <Collapsible open={open} onOpenChange={setOpen} className="mt-3">
      <CollapsibleTrigger className="flex items-center gap-1.5 text-xs font-medium text-muted-foreground hover:text-foreground transition-colors w-full">
        <ChevronDown className={`h-3 w-3 transition-transform ${open ? "" : "-rotate-90"}`} />
        <MapPin className="h-3 w-3" />
        Job Details (for career page)
      </CollapsibleTrigger>
      <CollapsibleContent className="mt-3">
        <div className="rounded-lg border border-border bg-muted/20 p-3 space-y-3">
          {!loaded ? (
            <div className="grid grid-cols-2 gap-3">
              {[1, 2, 3, 4].map((i) => (
                <div key={i} className="space-y-1">
                  <Skeleton className="h-3 w-20" />
                  <Skeleton className="h-8 w-full" />
                </div>
              ))}
            </div>
          ) : (
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1">
              <Label className="text-xs">Location</Label>
              <Input
                value={location}
                onChange={(e) => setLocation(e.target.value)}
                placeholder="e.g. San Francisco, CA"
